async function request(path,options={}){
 if(window.BrowserAtelier)return BrowserAtelier.request(path,options);

 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);
 try{const response=await fetch(path,{...options,signal:controller.signal});const result=await response.json();if(!response.ok){const error=new Error(result.error||'Erreur HTTP '+response.status);error.status=response.status;throw error}return result}finally{clearTimeout(timeout)}
}
async function ensureSession(force=false){
 if(force){session='';sessionPromise=null}if(session)return session;
 if(!sessionPromise)sessionPromise=request('/api/session').then(result=>session=result.token).finally(()=>sessionPromise=null);
 return sessionPromise;
}
async function refresh(){
 clearTimeout(timer);if(refreshing){timer=setTimeout(refresh,500);return}refreshing=true;
 const requestedTf=selectedTimeframe;
 try{const result=await request('/api/state?view=ui&timeframe='+requestedTf);online=true;failures=0;if(requestedTf===selectedTimeframe){if(state?.instanceId&&state.instanceId!==result.instanceId){agentConfig=null;ensureSession(true).catch(()=>{})}state=result;render()}}
 catch(error){online=false;failures++;text('status',failures>1?'● SERVEUR HORS LIGNE':'● RECONNEXION');$('status').className='tag stale';$('connection-banner').hidden=false;text('connection-banner','Données indisponibles. Les valeurs affichées peuvent être anciennes ; les actions restent bloquées. Nouvelle tentative automatique.');$('open-btn').disabled=true;$('close-btn').disabled=true;$('fill-atr').disabled=true;renderConnections()}
 finally{refreshing=false;timer=setTimeout(refresh,failures?Math.min(30000,2000*2**failures):document.hidden?15000:2000)}
}
async function action(path,args){
 if(busy||!online)return;busy=true;text('trade-message','Enregistrement…');render();
 try{await ensureSession();const options=()=>({method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session},body:JSON.stringify(args)});
 try{await request(path,options())}catch(error){if(error.status!==403)throw error;await ensureSession(true);await request(path,options())}
 text('trade-message','Simulation enregistrée.');$('trade-message').className='positive';await refresh();
 }catch(error){text('trade-message',error.name==='AbortError'?'Réponse non reçue. Vérifie la position avant de réessayer ; aucune répétition automatique.':error.message);$('trade-message').className='negative';await refresh()}
 finally{busy=false;if(state&&online)render()}
}
